import { copy, projects, localProject } from './data.js';
import { renderGrowthDemo, renderBriefDemo, initDemos, getGrowthReport } from './demos.js';
let animateFilterUpdate = (_grid, update) => update();
import { watchCoverImages } from './image-loading.js';

const params = new URLSearchParams(location.search);
const lang = params.get('lang') === 'zh' ? 'zh' : 'en';
const c = copy[lang], zh = lang === 'zh';
const items = projects.map(p => localProject(p, lang));
const e = v => String(v ?? '').replace(/[&<>"']/g, x => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const icon = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14"/></svg>';
const storyView = document.body.dataset.page === 'story' || params.get('view') === 'story';
if(document.body.dataset.page === 'story')document.documentElement.classList.add('story-document');
const viewQuery = storyView ? '&view=story' : '';
const home = (storyView ? './story.html' : './') + '?lang=' + lang;
const about = './about.html?lang=' + lang + viewQuery;
const workURL = id => home + (storyView ? '#story-' + (items.some(project => project.id === id) ? id : 'signal') : '#work');
const url = id => './project.html?id=' + encodeURIComponent(id) + '&lang=' + lang + viewQuery;
const badge = '<span class="fiction-badge"><i aria-hidden="true"></i>' + e(c.fiction) + '</span>';
const figureNote = (who, source) => '<figcaption>' + e(c.photo) + ' · <a href="' + source + '" target="_blank" rel="noopener noreferrer">' + e(who) + ' / Unsplash ↗</a></figcaption>';
document.documentElement.lang = zh ? 'zh-CN' : 'en';
document.querySelector('.skip-link').textContent = c.skip;
const localeURL = new URL(location.href); localeURL.searchParams.set('lang', zh ? 'en' : 'zh');
const localeLink = e(localeURL.pathname + localeURL.search + localeURL.hash);
const header = document.querySelector('.site-header');
header.innerHTML = `<a class="wordmark" href="${home}" aria-label="Alex Lin — ${zh ? '首页' : 'home'}">alex.</a><div class="header-actions"><nav class="desktop-nav" aria-label="${zh?'主导航':'Main navigation'}"><a href="${workURL()}">${e(c.work)}</a><a href="${about}">${e(c.about)}</a><a class="nav-contact" href="${about}#build">${e(c.build)}<span class="control-icon">${icon}</span></a></nav><a class="locale-switch" href="${localeLink}" lang="${zh?'en':'zh-CN'}" aria-label="${zh?'Switch to English':'切换到中文'}">${zh?'EN':'中文'}</a><button class="motion-toggle" type="button" aria-pressed="false" aria-label="${zh?'暂停页面动效':'Pause page motion'}"><span class="pause-mark" aria-hidden="true"><svg viewBox="0 0 20 20"><path d="M7 4v12M13 4v12"/></svg></span><span class="play-mark" aria-hidden="true"><svg viewBox="0 0 20 20"><path d="m6 4 9 6-9 6Z"/></svg></span></button><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="mobile-nav">${e(c.menu)}<span aria-hidden="true">＋</span></button></div><nav id="mobile-nav" class="mobile-nav" aria-label="${zh?'手机导航':'Mobile navigation'}" hidden><a href="${workURL()}">${e(c.work)}</a><a href="${about}">${e(c.about)}</a><a href="${about}#build">${e(c.build)} ↗</a></nav>`;

function signalVisual(hero=false) {
 const report=getGrowthReport();
 const sales=new Intl.NumberFormat(zh?'zh-CN':'en-US',{style:'currency',currency:'USD',currencyDisplay:'narrowSymbol',maximumFractionDigits:0}).format(report.totals.revenue);
 const orderCount=new Intl.NumberFormat(zh?'zh-CN':'en-US').format(report.totals.orders);
 const max=Math.max(...report.series.map(row=>row.revenue));
 const line=report.series.map((row,index)=>`${index?'L':'M'}${(index*460/(report.series.length-1)).toFixed(1)} ${(140-row.revenue/max*125).toFixed(1)}`).join('');
 return `<div class="signal-visual ${hero?'is-hero':''}"><div class="console-top"><span class="console-brand"><i aria-hidden="true"></i>signal<span class="console-dot">.</span></span><span class="console-period">${zh?'Morrow · 增长概览':'Morrow · growth overview'}</span><span class="console-avatar" aria-hidden="true">M</span></div><div class="console-layout"><div class="console-sidebar" aria-hidden="true"><span class="side-active">◉</span><span>▥</span><span>▧</span><span>↗</span><i></i><span>⚙</span></div><div class="console-body"><div class="console-heading"><div><span>${zh?'让下一步更清楚':'A little more clarity'}</span><strong>${zh?'每天，都向前一点。':'Good morning, Morrow.'}</strong></div><span class="console-market">US · UK · DE</span></div><div class="console-stats"><div><span>${zh?'商品销售额':'Gross sales'}</span><strong>${sales}</strong><small>↗ ${zh?'模拟周期':'sample period'}</small></div><div><span>${zh?'订单':'Orders'}</span><strong>${orderCount}</strong><small>${zh?'订单，非人数':'orders, not people'}</small></div><div><span>ROAS</span><strong>${report.metrics.roas.toFixed(2)}×</strong><small>${zh?'示意数据':'illustrative data'}</small></div></div><div class="console-chart"><div><strong>${zh?'增长的节奏':'The shape of progress'}</strong><span>${zh?'示意图 · USD':'Illustrative view · USD'}</span></div><svg viewBox="0 0 460 155" role="img" aria-label="${zh?'示意上升趋势线，完整案例中可查看实际模拟数据':'Illustrative upward chart; inspect the actual synthetic dataset in the case'}"><defs><linearGradient id="area-${hero?'hero':'card'}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#b3c681" stop-opacity=".5"/><stop offset="1" stop-color="#b3c681" stop-opacity="0"/></linearGradient></defs><path class="chart-grid" d="M0 25H460M0 70H460M0 115H460"/><path fill="url(#area-${hero?'hero':'card'})" d="${line}L460 155H0Z"/><path class="chart-line" d="${line}"/></svg><div class="chart-days"><span>SEP 01</span><span>SEP 14</span><span>SEP 28</span></div></div></div></div></div>`;
}
function briefVisual(){return `<div class="brief-visual"><div class="brief-mini-top"><span>briefly<span>✳</span></span><small>${zh?'一个清楚的起点':'A clearer starting point'}</small></div><div class="brief-mini-grid"><div class="brief-product"><div class="bottle" aria-hidden="true"><i></i><span>morrow<br>everyday</span></div><span>${zh?'日用水瓶':'Everyday bottle'}</span></div><div class="brief-paper"><span class="tiny-pill">${zh?'内容简报':'CONTENT BRIEF'}</span><h4>${zh?'小细节，\n好故事。':'Small detail.\nBetter story.'}</h4><div class="paper-lines" aria-hidden="true"><i></i><i></i><i></i></div><div class="brief-check">✓ ${zh?'先有方向，再开始创作':'A direction worth making'}</div></div></div></div>`;}
function researchVisual(){return `<div class="research-visual"><div class="research-label">fieldwork / 01</div><div class="research-note note-back"><span>03</span><p>${zh?'做什么？':'What could we build?'}</p></div><div class="research-note note-front"><span>${zh?'一个有用的问题':'A USEFUL QUESTION'}</span><h4>${zh?'现在，什么\n最值得做？':'What matters\nmost, next?'}</h4><div class="note-dots" aria-hidden="true"><i></i><i></i><i></i></div></div><div class="research-ruler" aria-hidden="true">+ &nbsp; + &nbsp; + &nbsp; + &nbsp; + &nbsp; + &nbsp; +</div></div>`;}
function cover(p){return p.id==='signal'?signalVisual():p.id==='briefly'?briefVisual():researchVisual();}
function card(p){return `<article class="project-card" data-layout data-category="${p.category}"><a class="project-card-link" href="${url(p.id)}"><div class="project-image tone-${p.tone}" data-layout="position">${cover(p)}<span class="project-open control-icon">${icon}</span></div><div class="project-copy" data-layout="position"><div class="card-meta"><span>${e(p.type)}</span><span>${p.year}</span></div><h3>${e(p.short)}</h3><p>${e(p.preview)}</p><span class="project-more">${e(c.readCase)} <span class="control-icon">${icon}</span></span></div></a></article>`;}
function homePage(){return `<section class="hero wrap" aria-labelledby="hero-title"><div class="hero-copy"><p class="hero-role"><span class="status-dot" aria-hidden="true"></span>${e(c.role)}</p><h1 id="hero-title"><span class="title-line"><span>${e(c.line1)}</span></span><span class="title-line"><span><em>${e(c.line2)}</em></span></span></h1><p class="hero-intro">${e(c.intro)}</p><div class="hero-buttons"><a class="button button-dark" href="#work">${e(c.workCTA)} <span class="control-icon">${icon}</span></a><a class="hero-about" href="${about}">${e(c.aboutCTA)} <span aria-hidden="true">↗</span></a></div><div class="hero-footnote">${badge}<p>${e(c.fictionNote)}</p></div></div><div class="hero-visual"><a class="hero-product-link" href="${url('signal')}" aria-label="${zh?'打开 Signal 完整案例与交互看板':'Open the full Signal case and interactive dashboard'}"><div class="hero-product-stage"><div class="visual-orbit orbit-one" aria-hidden="true"></div><div class="visual-orbit orbit-two" aria-hidden="true"></div><div class="hero-console">${signalVisual(true)}</div><div class="floating-insight"><span class="insight-symbol" aria-hidden="true">✳</span><div><small>${zh?'从观察，到行动':'FROM SIGNAL TO ACTION'}</small><strong>${zh?'清楚一点，就能向前一步。':'Clarity is a growth advantage.'}</strong></div></div><span class="stage-caption">${zh?'策略与产品，在这里相遇':'Where product meets momentum.'}<span class="control-icon">${icon}</span></span></div></a></div></section><section class="career-strip wrap" aria-label="${zh?'虚构履历速览':'Fictional career snapshot'}"><span class="strip-label">${zh?'虚构履历速览':'THE FICTIONAL CONTEXT'}</span><div><strong>6</strong><span>${e(c.heroYears)}</span></div><div><strong>3</strong><span>${e(c.heroMarkets)}</span></div><div><strong>$12.8M</strong><span>${e(c.heroMetric)}</span></div></section><section class="work-section wrap" id="work" aria-labelledby="work-title"><div class="section-heading"><div><p class="section-kicker">01 / ${zh?'项目':'THE WORK'}</p><h2 id="work-title">${e(c.work)}</h2></div><div class="filters" role="group" aria-label="${zh?'筛选项目':'Filter projects'}">${[['all',c.all],['growth',c.growth],['product',c.product],['research',c.research]].map(([v,t])=>`<button type="button" data-filter="${v}" aria-pressed="${v==='all'}">${e(t)}</button>`).join('')}</div></div><p class="work-intro">${e(c.workIntro)}</p><p id="filter-status" class="sr-only" role="status" aria-live="polite"></p><div class="project-grid" id="project-grid">${items.map(card).join('')}</div></section><section class="approach-section"><div class="wrap"><div class="approach-heading"><p class="section-kicker">02 / ${zh?'方法':'THE APPROACH'}</p><h2>${e(c.methodTitle).replace('\n','<br>')}</h2><p>${e(c.methodIntro)}</p></div><div class="approach-grid">${c.methods.map(([t,d],i)=>`<article><span class="method-number">0${i+1}</span><h3>${e(t)}</h3><p>${e(d)}</p></article>`).join('')}</div></div></section>`;}
function fieldwork(){const labels=zh?['决策简报','报表中心','自动化系统']:['Decision brief','Report hub','Automation suite'];return `<section class="fieldwork-demo" aria-labelledby="fieldwork-title"><div class="artifact-heading"><div><p class="section-kicker">${zh?'示例研究 · 虚构材料':'ILLUSTRATIVE RESEARCH · INVENTED MATERIAL'}</p><h2 id="fieldwork-title">${zh?'让机会走向一个选择':'From possibility to a choice'}</h2></div><span class="tiny-pill">6 → 3 → 1</span></div><div class="research-journey">${(zh?[['观察','分散的数据，重复的沟通'],['解释','团队缺少共用的决策起点'],['选择','先做一份可讨论的决策简报']]:[['Notice','Scattered reports. Repeated questions.'],['Interpret','No shared starting point for a decision.'],['Choose','A brief the team can discuss.']]).map(([t,d],i)=>`<div><span>0${i+1}</span><h3>${e(t)}</h3><p>${e(d)}</p></div>`).join('')}</div><div class="concept-controls" role="group" aria-label="${zh?'比较产品概念':'Compare product concepts'}">${labels.map((label,i)=>`<button type="button" data-concept="${i}" aria-pressed="${i===0}">${e(label)}</button>`).join('')}</div><div class="concept-result" role="status" aria-live="polite" data-concept-result></div><p class="artifact-limit">${zh?'此处用虚构研究与示意比较演示产品判断，并非真实访谈或商业验证。':'Invented research and an illustrative comparison demonstrate the decision process, not real interviews or commercial validation.'}</p></section>`;}
function casePage(){const p=items.find(p=>p.id===params.get('id'));if(!p){document.title=(zh?'未找到项目':'Case not found')+' — Alex Lin';return `<section class="wrap project-missing"><h1>${e(c.missing)}</h1><p>${e(c.missingText)}</p><a class="button button-dark" href="${workURL()}">${e(c.back)} ↗</a></section>`;}document.title=p.short+' — Alex Lin';return `<div class="wrap case-page"><a class="back-link" href="${workURL(p.id)}">↖ ${e(c.back)}</a><header class="project-title"><p class="hero-role">${e(p.type)} / ${p.year}</p><h1>${e(p.title)}</h1><p class="project-summary">${e(p.summary)}</p><div class="case-status">${badge}<span>${e(c.caseLabel)}</span></div></header><nav class="case-contents" aria-label="${zh?'本页内容':'Case contents'}"><span>${e(c.onPage)}</span><a href="#case-artifact">${e(c.artifact)}</a><a href="#case-process">${e(c.thinking)}</a><a href="#case-results">${e(c.results)}</a></nav><div class="case-intro"><div class="detail-cover tone-${p.tone}">${cover(p)}</div><section class="case-overview" aria-label="${e(c.snapshot)}"><div class="case-purpose"><h2>${e(c.taskLabel)}</h2><p>${e(p.question)}</p></div><div><h2>${e(c.roleLabel)}</h2><p>${e(p.role)}</p></div><dl>${p.facts.map(([a,b])=>`<div><dt>${e(a)}</dt><dd>${e(b)}</dd></div>`).join('')}</dl></section></div><section id="case-artifact" class="case-artifact">${p.id==='signal'?renderGrowthDemo(lang):p.id==='briefly'?renderBriefDemo(lang):fieldwork()}</section>${p.id==='briefly'?`<figure class="editorial-photo"><img src="./assets/photos/product.jpg" width="1800" height="1200" alt="${zh?'打开的纸箱与包装材料，作为电商内容工作的示意摄影':'An open cardboard shipping box, illustrative photography for commerce content work'}" loading="lazy">${figureNote('Kelli McClintock','https://unsplash.com/photos/brown-cardboard-box-DcoB_NoNl6U')}</figure>`:''}<section class="project-story" id="case-process"><div class="project-sections"><section class="case-challenge"><p class="section-kicker">${zh?'先理解问题':'START WITH THE PROBLEM'}</p><h2>${e(c.detailLabel)}</h2><p>${e(p.challenge)}</p></section>${p.decisions.map(([t,d],i)=>`<section class="decision-section"><span class="decision-number">0${i+1}</span><div><h2>${e(t)}</h2><p>${e(d)}</p></div></section>`).join('')}</div></section><section id="case-results" class="case-result"><p class="section-kicker">${e(c.scopeLabel)}</p><h2>${zh?'这个案例，展示了什么。':'What this case demonstrates.'}</h2><p>${e(p.outcome)}</p></section><nav class="case-browse" aria-label="${zh?'项目导航':'Case navigation'}"><a class="text-link case-back-list" href="${workURL(p.id)}">↖ ${e(c.back)}</a><div><span>${e(c.related)}</span>${items.filter(x=>x.id!==p.id).map(x=>`<a href="${url(x.id)}">${e(x.short)} ↗</a>`).join('')}</div></nav></div>`;}
function aboutPage(){document.title=(zh?'关于 Alex':'About Alex')+' — '+(zh?'作品集 UI 设计':'Portfolio UI Design');const timeline=zh?[['2023 — 2026','Northstar Studio','AI 产品与增长负责人','把跨境团队反复遇到的问题，转化为可以体验、讨论和验证的产品方案。'],['2020 — 2023','Morrow Commerce','增长运营 → 增长负责人','从内容测试与商品运营出发，建立跨市场增长分析和每周决策节奏。']]:[['2023 — 2026','Northstar Studio','AI Product & Growth Lead','Turning recurring commerce-team problems into product ideas people can use, discuss and evaluate.'],['2020 — 2023','Morrow Commerce','Growth Operator → Growth Lead','From content tests and commerce operations to cross-market analysis and a focused weekly decision rhythm.']];return `<section class="about-hero wrap"><div><p class="hero-role">${zh?'关于这个虚构人物':'MEET THE FICTIONAL CHARACTER'}</p><h1>${zh?'Alex Lin，\n把判断做成产品。':'A product mind.\nA growth instinct.'}</h1><div class="about-identity"><span class="profile-monogram" aria-hidden="true">al.</span><div><strong>Alex Lin</strong><span>${zh?'AI 产品与跨境增长':'AI Product & Growth Lead'}</span></div></div></div><div class="about-lead"><p>${zh?'我喜欢把复杂的问题，变成一个清楚、有用的下一步。':'I like turning a complicated question into a useful next step.'}</p><p>${zh?'这个人物有六年的虚构职业经历：先理解业务与用户，再把反复出现的问题做成产品。他的三个项目，用来展示运营判断、产品思维和实现能力如何相互配合。':'Alex’s six-year fictional career begins with understanding customers and commerce, then turns recurring problems into product opportunities. His three cases explore how growth judgement, product thinking and practical implementation work together.'}</p><div class="about-disclosure">${badge}<p>${e(c.fictionNote)}</p></div></div></section><section class="about-photo-section wrap"><figure class="about-photo"><img src="./assets/photos/workspace.jpg" width="1600" height="1067" alt="${zh?'灯光下的电脑与工作桌，示意工作环境':'A warmly lit desk with a laptop and lamp, used as illustrative workspace photography'}" loading="eager">${figureNote('Elijah Pilchard','https://unsplash.com/photos/a-desk-with-a-laptop-and-a-lamp-on-it-C51WQ7xqsAE')}</figure><div class="about-photo-note"><span class="section-kicker">${zh?'相信的工作方式':'A WAY OF WORKING'}</span><p>${zh?'好的想法，\n需要一个可以体验的版本。':'The idea gets better\nwhen you can use it.'}</p><a class="text-link" href="${url('briefly')}">${zh?'体验 Briefly':'Try Briefly'} <span class="control-icon">${icon}</span></a></div></section><section class="experience-section wrap"><div class="section-heading"><div><p class="section-kicker">${zh?'虚构的职业路径':'AN INVENTED CAREER PATH'}</p><h2>${zh?'从业务问题，到产品机会。':'From growth questions to product opportunities.'}</h2></div></div>${timeline.map(([date,name,role,text])=>`<article class="experience-row"><p class="experience-date">${date}</p><div><h3>${e(name)}</h3><p class="experience-role">${e(role)}</p><p>${e(text)}</p></div></article>`).join('')}<p class="experience-note">${zh?'以上公司、职位与经历为教学设定，不代表真实雇佣关系或雇主背书。':'The employers, roles and career history above are fictional teaching material, not verified employment or endorsements.'}</p></section><section id="build" class="build-section"><div class="wrap build-inner"><div><p class="section-kicker">${zh?'现在，换成你的故事':'NOW MAKE IT YOURS'}</p><h2>${zh?'保留方法，\n写出你的版本。':'Keep the method.\nMake it your story.'}</h2><p>${zh?'这个示例随开源技能提供。使用自己的真实材料，重新选择适合你的定位、案例、视觉与呈现方式。':'This example comes with the portfolio-website Skill. Bring your own real materials and choose the positioning, cases and visual direction that fit you.'}</p><a class="button button-dark" href="./assets/sample-resume.md" download>${e(c.sample)}<span aria-hidden="true">↓</span></a></div><ol class="build-steps">${(zh?[['梳理材料','从简历、作品与目标读者开始，说清本人贡献和证据。'],['做出体验','按作品类型选择图片、文档、数据或交互原型。'],['验证与发布','测试完整阅读路径，再部署为普通浏览器可以访问的网站。']]:[['Start with the materials','A résumé, work samples and a target reader. Keep contribution and evidence clear.'],['Make the work tangible','Choose imagery, documents, data or a working prototype to suit each case.'],['Test, then share','Exercise the full reader journey and deploy as an ordinary static website.']]).map(([t,d],i)=>`<li><span>0${i+1}</span><div><h3>${e(t)}</h3><p>${e(d)}</p></div></li>`).join('')}</ol></div></section>`;}
function storyPage(){
 document.title='Alex Lin — '+(zh?'把想法，做成下一步':'From a signal to something useful');
 const captions=zh?['看清增长','做出产品','选对方向']:['See the signal','Shape the product','Choose the next move'];
 const leads=zh?['把信息，变成判断。','把细节，变成方向。','把问题，变成选择。']:['Clarity before action.','Direction before production.','A choice before a roadmap.'];
 const chapter=(p,i)=>`<section class="story-chapter" id="story-${p.id}" aria-labelledby="story-title-${p.id}"><div class="story-chapter-heading wrap"><div><p class="story-eyebrow">0${i+1} / ${e(p.type)}</p><h2 id="story-title-${p.id}"><span>${e(p.name)}</span>${e(leads[i])}</h2></div><div><p>${e(p.summary)}</p><p class="story-role"><strong>${e(c.roleLabel)}</strong>${e(p.role)}</p></div></div><div class="story-artifact wrap">${p.id==='signal'?renderGrowthDemo(lang):p.id==='briefly'?renderBriefDemo(lang):fieldwork()}</div><div class="story-takeaways wrap"><div><span class="story-eyebrow">${zh?'问题':'THE QUESTION'}</span><h3>${e(p.question)}</h3></div><div>${p.decisions.slice(0,2).map(([title,text])=>`<article><h3>${e(title)}</h3><p>${e(text)}</p></article>`).join('')}<p class="story-scope">${e(p.outcome)}</p><a class="story-case-link" href="${url(p.id)}">${e(c.readCase)} ${icon}</a></div></div></section>`;
 return `<section class="story-hero wrap" aria-labelledby="story-heading"><div class="story-hero-copy"><p class="story-eyebrow">ALEX LIN / PRODUCT & GROWTH</p><h1 id="story-heading">${zh?'从一个信号，<br><em>到有用的下一步。</em>':'A little signal.<br><em>A better next move.</em>'}</h1><p class="story-intro">${zh?'理解业务，做出产品，再从反馈里找到方向。往下看，三个项目串起我解决问题的方式。':'Understand the business. Make something useful. Learn what to do next. Three projects, one way of thinking.'}</p><div class="story-hero-note">${badge}<p>${e(c.fictionNote)}</p></div><a class="story-scroll" href="#story-signal">${zh?'向下，走进项目':'SCROLL INTO THE WORK'}<span aria-hidden="true">↓</span></a><a class="view-switch" href="./index.html?lang=${lang}">${zh?'切换到卡片浏览版':'Switch to the gallery view'} ↗</a></div><div class="story-scene" aria-label="${zh?'Signal 的立体分层界面示意；下方可直接操作完整看板':'A layered Signal interface illustration; the full dashboard is usable below'}"><div class="story-orbit orbit-a" aria-hidden="true"></div><div class="story-orbit orbit-b" aria-hidden="true"></div><div class="story-glow" aria-hidden="true"></div><div class="story-plane plane-back" aria-hidden="true"><span>01 — NOTICE</span><strong>${zh?'信息，不等于方向。':'More data.\nLess noise.'}</strong><div class="plane-rule"></div></div><div class="story-plane plane-main">${signalVisual(true)}</div><div class="story-plane plane-front"><span class="story-asterisk" aria-hidden="true">✳</span><div><small>${zh?'从观察，到行动':'FROM SIGNAL TO ACTION'}</small><strong>${zh?'看清楚，才能往前走。':'Make the next move count.'}</strong></div></div><span class="story-scene-caption">01 / OBSERVE → BUILD → LEARN</span></div></section><nav class="story-rail" aria-label="${zh?'项目章节':'Project chapters'}"><a href="#story-signal">01 <span>Signal</span></a><a href="#story-briefly">02 <span>Briefly</span></a><a href="#story-fieldwork">03 <span>Fieldwork</span></a><a href="#story-person">04 <span>${zh?'关于':'About'}</span></a></nav><div class="story-opening wrap"><p>${zh?'不止于一个想法。':'Ideas are a beginning.'}</p><h2>${zh?'把问题讲清楚，<br>把答案做出来。':'The work is in<br><em>making it useful.</em>'}</h2><div><span>6 ${zh?'年虚构经历':'fictional years'}</span><span>3 ${zh?'个示例市场':'illustrative markets'}</span><span>$12.8M ${zh?'虚构累计 GMV':'fictional cumulative GMV'}</span></div></div>${items.map(chapter).join('')}<section class="story-person wrap" id="story-person"><div><p class="story-eyebrow">04 / ${zh?'人物与方法':'THE PERSON & THE PRACTICE'}</p><h2>${zh?'始终在意的，<br>是下一步有用。':'A product mind.<br><em>A growth instinct.</em>'}</h2><p>${zh?'这段虚构履历，从电商运营出发，再走向 AI 产品与增长。贯穿其中的，是把模糊问题做成具体、可以讨论的东西。':'Alex’s fictional path moves from commerce operations to AI product and growth work. The thread is turning an ambiguous problem into something concrete enough to use, discuss and improve.'}</p><div class="story-person-actions"><a class="button button-dark" href="./assets/sample-resume.md" download>${e(c.sample)} ↓</a><a href="${about}">${e(c.aboutCTA)} ↗</a></div></div><div class="story-timeline">${(zh?[['2023—2026','Northstar Studio','AI 产品与增长负责人'],['2020—2023','Morrow Commerce','增长运营 → 增长负责人']]:[['2023—2026','Northstar Studio','AI Product & Growth Lead'],['2020—2023','Morrow Commerce','Growth Operator → Growth Lead']]).map(([date,name,role])=>`<article><span>${date}</span><h3>${name}</h3><p>${role}</p></article>`).join('')}<p class="story-scope">${e(c.fictionNote)} ${zh?'公司与职位同为教学设定。':'Employers and roles are also invented for teaching.'}</p></div></section>`;
}

const page = document.body.dataset.page;
document.querySelector('#app').innerHTML = page==='project'?casePage():page==='about'?aboutPage():page==='story'?storyPage():homePage();
if(page==='home'){const variant=document.createElement('a');variant.className='view-switch';variant.href='./story.html?lang='+lang;variant.textContent=zh?'试试连续滚动版 ↗':'Try the scrolling version ↗';document.querySelector('.hero-copy').append(variant);}
if(page==='home')document.title='Alex Lin — '+(zh?'把好想法做成好产品':'Good ideas. Made useful.');
document.querySelector('.site-footer').innerHTML = `<a class="footer-invitation" href="${about}#build"><span class="footer-phrase">${e(c.footer)}</span><span class="footer-arrow control-icon">${icon}</span></a><p class="footer-sub">${e(c.footerSub)}</p><div class="footer-bottom"><span>alex. / ${e(c.source)}</span><a href="#main">${e(c.top)} ↑</a><span>© 2026</span></div>`;

const syncLocaleLink = () => {
 const next = new URL(location.href);
 next.searchParams.set('lang', zh ? 'en' : 'zh');
 document.querySelector('.locale-switch').href = next.pathname + next.search + next.hash;
};
window.addEventListener('hashchange', syncLocaleLink);
window.addEventListener('pageshow', syncLocaleLink);
const menu = document.querySelector('.menu-toggle'), mobile = document.querySelector('#mobile-nav');
const closeMenu=(focus=false)=>{mobile.hidden=true;menu.setAttribute('aria-expanded','false');if(focus)menu.focus();};
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';mobile.hidden=!open;menu.setAttribute('aria-expanded',String(open));});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&!mobile.hidden)closeMenu(true);});
document.addEventListener('click',ev=>{if(!mobile.hidden&&!mobile.contains(ev.target)&&!menu.contains(ev.target))closeMenu();});
mobile.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>closeMenu()));
matchMedia('(min-width: 701px)').addEventListener('change',ev=>{if(ev.matches)closeMenu();});
const updateHeader=()=>header.classList.toggle('is-scrolled',scrollY>36);window.addEventListener('scroll',updateHeader,{passive:true});window.addEventListener('pageshow',updateHeader);updateHeader();
let filterVersion=0;
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{const value=button.dataset.filter,version=++filterVersion;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.dispatchEvent(new CustomEvent('folio:filter'));const grid=document.querySelector('#project-grid');animateFilterUpdate(grid,()=>{if(version!==filterVersion)return;let count=0;grid.querySelectorAll('.project-card').forEach(card=>{card.hidden=value!=='all'&&card.dataset.category!==value;if(!card.hidden)count++;});grid.dataset.filtered=String(value!=='all');document.querySelector('#filter-status').textContent=zh?`显示 ${count} 个项目`:`Showing ${count} ${count===1?'case':'cases'}`;});}));
const conceptOutput=document.querySelector('[data-concept-result]');
if(conceptOutput){const concepts=zh?[[ '决策简报','低投入 · 高学习价值','先把团队最常见的问题，变成一份可以一起检查与讨论的简报。下一步观察：它能否帮助团队明确一个行动？'],['报表中心','中投入 · 中学习价值','整合信息有价值，但先要理解团队到底要用这些数字做什么决定。下一步验证：哪些信息真正改变了行动？'],['自动化系统','高投入 · 待验证价值','自动化可以覆盖更多流程，也引入更多依赖。先用小范围原型验证输入、失败恢复和人工接管。']]:[['Decision brief','Low effort · high learning value','Start with a brief the team can inspect together. Next test: does it help people choose one clear action?'],['Report hub','Medium effort · medium learning value','Bringing reports together has value, but first learn which information actually changes a decision.'],['Automation suite','High effort · unvalidated value','A broad suite adds dependencies. Start by testing inputs, failure recovery and human handover in a small prototype.']];const setConcept=i=>{document.querySelectorAll('[data-concept]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.concept)===i)));const[t,meta,d]=concepts[i];conceptOutput.innerHTML=`<div><span class="tiny-pill">${e(meta)}</span><h3>${e(t)}</h3><p>${e(d)}</p></div><span class="concept-symbol" aria-hidden="true">${i===0?'↗':i===1?'◉':'✳'}</span>`;};setConcept(0);document.querySelectorAll('[data-concept]').forEach(b=>b.addEventListener('click',()=>setConcept(Number(b.dataset.concept))));}
document.querySelectorAll('.button,.nav-contact,.filters button').forEach(element=>{const content=document.createElement('span');content.className='control-content';while(element.firstChild)content.append(element.firstChild);element.append(content);});
initDemos();
watchCoverImages();
import('./effects.js').then(motion => {
 motion.bootMotion();
 animateFilterUpdate = motion.animateFilterUpdate;
}).catch(() => {
 document.documentElement.dataset.motion = 'off';
 const toggle = document.querySelector('.motion-toggle');
 toggle.disabled = true;
 toggle.setAttribute('aria-label', zh ? '页面动效不可用' : 'Page motion unavailable');
});
if(page==='story')import('./story-motion.js').then(module=>module.initStoryMotion()).catch(()=>{});
if(location.hash){requestAnimationFrame(()=>{let fragment=location.hash.slice(1);try{fragment=decodeURIComponent(fragment);}catch{/* Ignore malformed optional fragments. */}const target=document.getElementById(fragment);target?.scrollIntoView({block:'start',behavior:'instant'});});}
